/// <summary>
/// Sets total volume
/// </summary>
/// <param name = "_volume">Volume</param>
/// <returns>Volume</returns>
public Volume parmTotalVolume(Volume _volume = totalVolume)
{
    totalVolume = _volume;
    return totalVolume;
}

/// <summary>
/// set or get <c>METTransferOrderExtractScreenParameters</c> class instance.
/// </summary>
/// <param name = "_metTransferOrderExtractScreenParameters"><c>METTransferOrderExtractScreenParameters</c> class instance.</param>
/// <returns><c>METTransferOrderExtractScreenParameters</c> class instance</returns>
public METTransferOrderExtractScreenParameters parmMETTransferOrderExtractScreenParams(
    METTransferOrderExtractScreenParameters _metTransferOrderExtractScreenParameters = metTransferOrderExtractScreenParameters)
{
    metTransferOrderExtractScreenParameters = _metTransferOrderExtractScreenParameters;
    return metTransferOrderExtractScreenParameters;
}

    /// <summary>
    /// set or get <c>METTransferOrderExtractScreenTmp</c> table instance.
    /// </summary>
    /// <param name = "_metTransferOrderExtractScreenTmp"><c>METTransferOrderExtractScreenTmp</c> table instance</param>
    /// <returns><c>METTransferOrderExtractScreenTmp</c> table instance</returns>
    public METTransferOrderExtractScreenTmp parmMETTransferOrderExtractScreenTmp(
        METTransferOrderExtractScreenTmp _metTransferOrderExtractScreenTmp = metTransferOrderExtractScreenTmp)
    {
        metTransferOrderExtractScreenTmp.linkPhysicalTableInstance(_metTransferOrderExtractScreenTmp);

        return metTransferOrderExtractScreenTmp;
    }

/// <summary> /// Extracts all the orders by salesid and category based on the filters. /// </summary> public void insertOrders() { //Case1: Insert records group by SalesId & Category insert_recordset metTransferOrderExtractScreenTmp(TransferId, LineNum, FilterCodeOne) select TransferId, minof(LineNum) from inventTransferLine group by inventTransferLine.TransferId, itemSiteSettings.FilterCode1 join inventTransferTable where inventTransferTable.TransferId == inventTransferLine.TransferId && inventTransferTable.TransferStatus == InventTransferStatus::Created && (!fromWarehouse || inventTransferTable.InventLocationIdFrom == fromWarehouse) && (!toWarehouse || inventTransferTable.InventLocationIdTo == toWarehouse) && (!shippingDate || inventTransferTable.ShipDate == shippingDate) join metInventTransferTableExt where metInventTransferTableExt.InventTransferTable == inventTransferTable.RecId && metInventTransferTableExt.OrderExtractStatus != METOrderExtractStatus::Extracted && (!route || metInventTransferTableExt.Route == route) join inventDim where inventDim.inventDimId == inventTransferLine.InventDimId join FilterCode1 from itemSiteSettings where itemSiteSettings.ItemId == inventTransferLine.ItemId && itemSiteSettings.InventSiteId == inventDim.InventSiteId && (!category || itemSiteSettings.FilterCode1 == category);
//Update the Itemtype update_recordset metTransferOrderExtractScreenTmp setting ItemType = itemSiteSettings.ItemType join RecId from inventTransferLine where inventTransferLine.TransferId == metTransferOrderExtractScreenTmp.TransferId && inventTransferLine.LineNum == metTransferOrderExtractScreenTmp.LineNum join RecId from inventDim where inventDim.inventDimId == inventTransferLine.InventDimId join ItemType from itemSiteSettings where itemSiteSettings.ItemId == inventTransferLine.ItemId && itemSiteSettings.InventSiteId == inventDim.InventSiteId && itemSiteSettings.FilterCode1 == metTransferOrderExtractScreenTmp.FilterCodeOne;
//Update order split category code update_recordset metTransferOrderExtractScreenTmp setting OSCCode = metReqItemTable.OSCCode join RecId from inventTransferLine where inventTransferLine.TransferId == metTransferOrderExtractScreenTmp.TransferId && inventTransferLine.LineNum == metTransferOrderExtractScreenTmp.LineNum join RecId from inventDim where inventDim.inventDimId == inventTransferLine.InventDimId join ItemType from itemSiteSettings where itemSiteSettings.ItemId == inventTransferLine.ItemId && itemSiteSettings.InventSiteId == inventDim.InventSiteId && itemSiteSettings.FilterCode1 == metTransferOrderExtractScreenTmp.FilterCodeOne join Recid from reqItemTable where reqItemTable.ItemId == inventTransferLine.ItemId join OSCCode from metReqItemTable where metReqItemTable.RefRecId == reqItemTable.RecId exists join inventDimReq where inventDimReq.InventSiteId == inventDim.InventSiteId && InventDimReq.InventLocationId == inventDim.InventLocationId && inventDimReq.inventDimId == reqItemTable.CovInventDimId;
}

    /// <summary>
    /// Calculates the sum of Weight, Volume, Case and Broken case values of the orders extracted.
    /// </summary>
    /// <param name = "_metTransferOrderExtractScreenTmp"><c>METTransferOrderExtractScreenTmp</c> table instance</param>
    public void calculate(METTransferOrderExtractScreenTmp  _metTransferOrderExtractScreenTmp)
    {
        metTransferOrderExtractScreenTmp.linkPhysicalTableInstance(_metTransferOrderExtractScreenTmp);

        //Clear computed values before calculating.
        update_recordset metTransferOrderExtractScreenTmp
            setting weight = 0, Volume = 0, Cases = 0, BrokenCase = 0;

        //METTransferOrderExtractScreenSiteView holds UOM data from custom physical dimensions by site form  by salesId, category, site & warehouse
        //so we insert to temp table for grouping by SalesId & Category
        insert_recordset metTransferOrderExtractScreenUOMSiteTmp (TransferId, Category, Weight, Volume)
            select TransferId, Category, sum(Weight), sum(Volume) from metTransferOrderExtractScreenSiteView group by TransferId, category
                where  (!fromWarehouse || metTransferOrderExtractScreenSiteView.InventLocationIdFrom == fromWarehouse)
                && (!toWarehouse || metTransferOrderExtractScreenSiteView.InventLocationIdTo == toWarehouse);

        //Case2: Update weight, volume for Case1 records where Item, Site & UOM matches
        update_recordset metTransferOrderExtractScreenTmp
            setting weight =  metTransferOrderExtractScreenUOMSiteTmp.Weight,
                    Volume =  metTransferOrderExtractScreenUOMSiteTmp.Volume
            join Weight, Volume from metTransferOrderExtractScreenUOMSiteTmp
                where metTransferOrderExtractScreenUOMSiteTmp.TransferId == metTransferOrderExtractScreenTmp.TransferId
                && metTransferOrderExtractScreenUOMSiteTmp.Category == metTransferOrderExtractScreenTmp.FilterCodeOne;

        //Case3: Update weight, volume for Case1 records where Item & Site matches. Conversion required
        while select forupdate metTransferOrderExtractScreenTmp
            join  ItemId, QtyTransfer, UnitId, InventDimId from inventTransferLine
                where  inventTransferLine.TransferId == metTransferOrderExtractScreenTmp.TransferId
            join InventSiteId from inventDim
                where inventDim.inventDimId == inventTransferLine.InventDimId
            join firstonly metWHSPhysDimUOMSite
                where metWHSPhysDimUOMSite.ItemId == inventTransferLine.ItemId
                && metWHSPhysDimUOMSite.SiteId == inventDim.InventSiteId
                && metWHSPhysDimUOMSite.UOM != inventTransferLine.UnitId
            exists join itemSiteSettings
                where itemSiteSettings.ItemId == inventTransferLine.ItemId
                &&  itemSiteSettings.InventSiteId == inventDim.InventSiteId
                &&  itemSiteSettings.FilterCode1 == metTransferOrderExtractScreenTmp.FilterCodeOne
            notexists join metWHSPhysDimUOMSiteJoin //Tow lines with same category and different site UOM
                where metWHSPhysDimUOMSiteJoin.ItemId == inventTransferLine.ItemId
                && metWHSPhysDimUOMSiteJoin.SiteId == inventDim.InventSiteId
                && metWHSPhysDimUOMSiteJoin.UOM == inventTransferLine.UnitId
        {
            metTransferOrderExtractScreenTmp.reread();
            ttsbegin;
            factor = EcoResProductUnitConverter::convertForReleasedProduct(
                    metWHSPhysDimUOMSite.ItemId,
                    inventTransferLine.inventDimId,
                    1,
                    EcoResReleasedProductUnitConverter::findUnitRecIdBySymbol(metWHSPhysDimUOMSite.UOM),
                    EcoResReleasedProductUnitConverter::findUnitRecIdBySymbol(inventTransferLine.UnitId),
                    NoYes::No,
                    NoYes::No);

            if (factor)
            {
                metTransferOrderExtractScreenTmp.Weight += inventTransferLine.QtyTransfer * (metWHSPhysDimUOMSite.Weight/factor);
                metTransferOrderExtractScreenTmp.Volume += inventTransferLine.QtyTransfer * (metWHSPhysDimUOMSite.displayVolume()/factor);
            }
            metTransferOrderExtractScreenTmp.update();
            ttscommit;
        }

        delete_from metTransferOrderExtractScreenUOMSiteTmp;
        //METOrderExtractScreenPhysDimView holds UOM data from standard Physical dimensions form by salesId, category, site & warehouse
        //so we insert to temp table for grouping by SalesId & Category
        insert_recordset metTransferOrderExtractScreenUOMSiteTmp (TransferId, Category, Weight, Volume)
            select TransferId, Category, sum(Weight), sum(Volume) from metTransferOrderExtractScreenPhysDimView group by TransferID, category
                where  (!fromWarehouse || metTransferOrderExtractScreenPhysDimView.InventLocationIdFrom == fromWarehouse)
                && (!toWarehouse || metTransferOrderExtractScreenPhysDimView.InventLocationIdTo == toWarehouse)
            exists join  inventTransferLine
                where  inventTransferLine.ItemId == metTransferOrderExtractScreenPhysDimView.ItemId
                && inventTransferLine.TransferId == metTransferOrderExtractScreenPhysDimView.TransferId
                && inventTransferLine.UnitId == metTransferOrderExtractScreenPhysDimView.UnitId
            exists join inventDim
                where inventDim.inventDimId == inventTransferLine.InventDimId
            exists join itemSiteSettings
                where itemSiteSettings.ItemId == inventTransferLine.ItemId
                &&  itemSiteSettings.InventSiteId == inventDim.InventSiteId
                &&  itemSiteSettings.FilterCode1 == metTransferOrderExtractScreenPhysDimView.Category
            exists join whsPhysDimUOMJoin
                where whsPhysDimUOMJoin.ItemId == inventTransferLine.ItemId
                && whsPhysDimUOMJoin.UOM == inventTransferLine.UnitId
            notexists join metWHSPhysDimUOMSiteJoin
                where metWHSPhysDimUOMSiteJoin.ItemId == inventTransferLine.ItemId
                && metWHSPhysDimUOMSiteJoin.SiteId == inventDim.InventSiteId;

        //Case4: Update weight, volume for Case1 records where Item, Site & UOM matches
        update_recordset metTransferOrderExtractScreenTmp
            setting weight = metTransferOrderExtractScreenTmp.weight +  metTransferOrderExtractScreenUOMSiteTmp.Weight,
                    Volume = metTransferOrderExtractScreenTmp.Volume +  metTransferOrderExtractScreenUOMSiteTmp.Volume
            join Weight, Volume from metTransferOrderExtractScreenUOMSiteTmp
                where metTransferOrderExtractScreenUOMSiteTmp.TransferId == metTransferOrderExtractScreenTmp.TransferId
                && metTransferOrderExtractScreenUOMSiteTmp.Category == metTransferOrderExtractScreenTmp.FilterCodeOne;

 
        //Case5: Update weight, volume for records where Item matches. Conversion required
        while select forupdate metTransferOrderExtractScreenTmp
            join  ItemId, QtyTransfer, UnitId, InventDimId from inventTransferLine
                where  inventTransferLine.TransferId == metTransferOrderExtractScreenTmp.TransferId
            join InventSiteId from inventDim
                where inventDim.inventDimId == inventTransferLine.InventDimId
            join firstonly1  whsPhysDimUOM
                where whsPhysDimUOM.ItemId == inventTransferLine.ItemId
                && whsPhysDimUOM.UOM != inventTransferLine.UnitId
            exists join itemSiteSettings
                where itemSiteSettings.ItemId == inventTransferLine.ItemId
                &&  itemSiteSettings.InventSiteId == inventDim.InventSiteId
                &&  itemSiteSettings.FilterCode1 == metTransferOrderExtractScreenTmp.FilterCodeOne
            notexists join metWHSPhysDimUOMSite
                where metWHSPhysDimUOMSite.ItemId == inventTransferLine.ItemId
                && metWHSPhysDimUOMSite.SiteId == inventDim.InventSiteId

        {
            //notexists join is not working and so a seperate call is made
            select firstonly RecId from whsPhysDimUOMJoin 
                where whsPhysDimUOMJoin.ItemId == inventTransferLine.ItemId
                && whsPhysDimUOMJoin.UOM == inventTransferLine.UnitId;
            if (whsPhysDimUOMJoin.RecId)
            {
                continue;
            }
            ttsbegin;

            factor = EcoResProductUnitConverter::convertForReleasedProduct(
                        whsPhysDimUOM.ItemId,
                        inventTransferLine.inventDimId,
                        1,
                        EcoResReleasedProductUnitConverter::findUnitRecIdBySymbol(whsPhysDimUOM.UOM),
                        EcoResReleasedProductUnitConverter::findUnitRecIdBySymbol(inventTransferLine.UnitId),
                        NoYes::No,
                        NoYes::No);
            if (factor)
            {
                metTransferOrderExtractScreenTmp.Weight += inventTransferLine.QtyTransfer * (whsPhysDimUOM.Weight/factor);
                metTransferOrderExtractScreenTmp.Volume += inventTransferLine.QtyTransfer * (whsPhysDimUOM.displayVolume()/factor);
            }
            metTransferOrderExtractScreenTmp.update();
            ttscommit;
        }

        //Case5: Update ItemType, Case, Broken case
        while select forupdate metTransferOrderExtractScreenTmp
            join  ItemId, QtyTransfer, UnitId, InventDimId from inventTransferLine
                where  inventTransferLine.TransferId == metTransferOrderExtractScreenTmp.TransferId
            join InventSiteId from inventDim
                where inventDim.inventDimId == inventTransferLine.InventDimId
            join ItemType from itemSiteSettings
                where itemSiteSettings.ItemId == inventTransferLine.ItemId
                &&  itemSiteSettings.InventSiteId == inventDim.InventSiteId
                &&  itemSiteSettings.FilterCode1 == metTransferOrderExtractScreenTmp.FilterCodeOne
        {
            ttsbegin;
            metTransferOrderExtractScreenTmp.reread();
            metTransferOrderExtractScreenTmp.Cases    +=  inventTransferLine.displayMETcases();
            metTransferOrderExtractScreenTmp.BrokenCase +=  inventTransferLine.displayMETBrokenCase();
            metTransferOrderExtractScreenTmp.update();
            ttscommit;
        }

        select sum(Volume) from metTransferOrderExtractScreenTmp;
        this.parmTotalVolume(metTransferOrderExtractScreenTmp.Volume);

    }

    /// <summary>
    /// Constructs the transfer order extract screen.
    /// </summary>
    /// <param name="_metTransferOrderExtractScreenTmp">
    /// The <c>METTransferOrderExtractScreenTmp</c> instance.
    /// </param>
    /// <param name="_metTransferOrderExtractScreenParameters">
    /// An instance of <c>METTransferOrderExtractScreenParameters</c> to filter the order extract screen form.
    /// </param>
    /// <returns>METTransferOrderExtractScreenProcessor class instance.</returns>
    public static METTransferOrderExtractScreenProcessor construct(
        METTransferOrderExtractScreenTmp                _metTransferOrderExtractScreenTmp,
        METTransferOrderExtractScreenParameters         _metTransferOrderExtractScreenParameters)
    {
        METTransferOrderExtractScreenProcessor   metTransferOrderExtractScreenProcessor;

        metTransferOrderExtractScreenProcessor = new METTransferOrderExtractScreenProcessor();

        metTransferOrderExtractScreenProcessor.populateOrderExtractScreen(_metTransferOrderExtractScreenTmp, _metTransferOrderExtractScreenParameters);

        return metTransferOrderExtractScreenProcessor;
    }

/// <summary>
/// Initialise parameters.
/// </summary>
protected void initParams()
{
    fromWarehouse   = metTransferOrderExtractScreenParameters.parmFromWarehouse();
    toWarehouse     = metTransferOrderExtractScreenParameters.parmToWarehouse();
    route           = metTransferOrderExtractScreenParameters.parmRoute();
    shippingDate    = metTransferOrderExtractScreenParameters.parmShippingDateConfirm();
    category        = metTransferOrderExtractScreenParameters.parmCategory();
}

    /// <summary>
    /// Populates <c>METTransferOrderExtractScreenTmp</c> table for the grid on the order extract screen form.
    /// </summary>
    /// <param name="_metTransferOrderExtractScreenTmp">
    /// The <c>METTransferOrderExtractScreenTmp</c> instance.
    /// </param>
    /// <param name="_metTransferOrderExtractScreenParameters">
    /// An instance of <c>METTransferOrderExtractScreenParameters</c> to filter the order extract screen form.
    /// </param>
    public void populateOrderExtractScreen(METTransferOrderExtractScreenTmp                _metTransferOrderExtractScreenTmp,
                                            METTransferOrderExtractScreenParameters         _metTransferOrderExtractScreenParameters)
    {
        METTransferOrderExtractScreenProcessor           metTransferOrderExtractScreenProcessor;

        metTransferOrderExtractScreenProcessor = new METTransferOrderExtractScreenProcessor();

        metTransferOrderExtractScreenProcessor.parmMETTransferOrderExtractScreenParams(_metTransferOrderExtractScreenParameters);
        metTransferOrderExtractScreenProcessor.parmMETTransferOrderExtractScreenTmp(_metTransferOrderExtractScreenTmp);
        metTransferOrderExtractScreenProcessor.initParams();
        metTransferOrderExtractScreenProcessor.insertOrders();
        this.parmTotalVolume(metTransferOrderExtractScreenProcessor.parmTotalVolume());
    }
